import json,sys,collections
SCIP={"IMPORTS","CALLS","CONSTRUCTS","ASYNC_CALLS","EXTENDS","INHERITS","IMPLEMENTS","OVERRIDES","USES_TYPE","PARAM_TYPE","RETURNS_TYPE","READS_FIELD","WRITES_FIELD","ACCESSES"}
files={};syms={}
lang=collections.defaultdict(lambda:[0,0,0])
slrel=collections.Counter(); slocc=collections.Counter(); occ=0; occw=0
sl_same=0; calls_noev=0; calls=0
fkeys=None
for line in open(sys.argv[1]):
    r=json.loads(line); t=r.get("record_type")
    if t=="file":
        if fkeys is None: fkeys=list(r.keys())
        files[r.get("path")]=r.get("language")
    elif t=="symbol": syms[r["id"]]=(r.get("file_path"),r.get("start_line"),r.get("end_line"))
    elif t=="relation":
        ev=r.get("evidence") or []
        if r["type"]=="CALLS":
            calls+=1
            if not ev: calls_noev+=1
        any_sl=False
        for e in ev:
            if not e.get("file_path") or not e.get("start_line"): continue
            w=e["end_line"]-e["start_line"]+1
            l=files.get(e["file_path"])
            L=lang[l]; L[0]+=1; L[1]+=(w>1); L[2]+=w
            if r["type"] in SCIP:
                occ+=1; occw+=w
                if w==1:
                    slocc[r["type"]]+=1; any_sl=True
                    s=syms.get(r["from_id"])
                    if s and s==(e["file_path"],e["start_line"],e["end_line"]): sl_same+=1
        if any_sl: slrel[r["type"]]+=1
print("file keys",fkeys)
